<script setup>
import {ref,computed,watch} from 'vue';
import {api} from '../services/accounting.js';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import FormDialog from '../components/FormDialog.vue';
import FarmExpenseClassification from '../components/FarmExpenseClassification.vue';
import {companyHasCapability} from '../../../shared/company-formats.js';
const {company}=useContext(),{can}=useAccess();
const farms=ref([]),groups=ref([]),expenses=ref([]),farmId=ref(''),groupId=ref(''),farmForm=ref(null),groupForm=ref(null),selectedExpense=ref(null),busy=ref(false),error=ref('');let generation=0;
const currentFarm=computed(()=>farms.value.find(farm=>String(farm.id)===farmId.value));
const currentGroups=computed(()=>groups.value.filter(group=>String(group.farm_id)===farmId.value));
function message(cause){return {FARM_DUPLICATE_CODE:'Ja existeix una granja amb aquest codi.',FARM_DUPLICATE_GROUP:'Ja existeix un grup amb aquest nom dins la granja.',FARM_CHANGED:'Les dades han canviat. Actualitza la pantalla.'}[cause.code]||'No s’ha pogut completar l’operació ('+cause.code+').';}
async function load(){const ticket=++generation;error.value='';try{const [catalog,rows]=await Promise.all([api('/farm-organization'),api('/farm-organization/expenses?'+new URLSearchParams({...(farmId.value?{farm_id:farmId.value}:{}),...(groupId.value?{group_id:groupId.value}:{})}))]);if(ticket!==generation)return;farms.value=catalog.farms;groups.value=catalog.groups;expenses.value=rows;}catch(cause){if(ticket===generation)error.value=message(cause);}}
watch(()=>company.value?.id,()=>{farmId.value='';groupId.value='';farmForm.value=null;groupForm.value=null;selectedExpense.value=null;farms.value=[];groups.value=[];expenses.value=[];void load();},{immediate:true});
function selectFarm(value){farmId.value=value;groupId.value='';void load();}
async function saveFarm(){if(busy.value)return;busy.value=true;error.value='';const owner=company.value?.id;try{const form={...farmForm.value},result=await api('/farm-organization/farms'+(form.id?'/'+form.id:''),{method:form.id?'PATCH':'POST',body:form});if(owner!==company.value?.id)return;farmForm.value=null;farmId.value=String(result.id);groupId.value='';await load();}catch(cause){error.value=message(cause);}finally{busy.value=false;}}
async function saveGroup(){if(busy.value)return;busy.value=true;error.value='';const owner=company.value?.id;try{const form={...groupForm.value};await api('/farm-organization/farms/'+form.farm_id+'/groups'+(form.id?'/'+form.id:''),{method:form.id?'PATCH':'POST',body:form});if(owner!==company.value?.id)return;groupForm.value=null;await load();}catch(cause){error.value=message(cause);}finally{busy.value=false;}}
</script>
<template>
 <div class="page-heading"><div><h1>Gestió de granges</h1><p class="muted">Granges, grups i despeses classificades.</p></div><button v-if="can('accounting_write')" class="button primary" @click="farmForm={code:'',name:'',notes:''}">Nova granja</button></div>
 <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p>
 <div class="filters"><label>Granja<select :value="farmId" @change="selectFarm($event.target.value)"><option value="">Totes les granges</option><option v-for="farm in farms" :key="farm.id" :value="String(farm.id)">{{ farm.code }} · {{ farm.name }}</option></select></label><label>Grup<select v-model="groupId" :disabled="!farmId" @change="load"><option value="">Tots els grups</option><option v-for="group in currentGroups" :key="group.id" :value="String(group.id)">{{ group.name }}</option></select></label><button class="button" @click="load">Actualitzar</button></div>
 <section v-if="!currentFarm" class="panel organization-panel"><h2>Granges</h2><p v-if="!farms.length">Encara no hi ha granges.</p><div v-for="farm in farms" :key="farm.id" class="organization-row"><button class="button" @click="selectFarm(String(farm.id))">{{ farm.code }} · {{ farm.name }}</button><span>{{ groups.filter(group=>group.farm_id===farm.id).length }} grups</span></div></section>
 <section v-else class="panel organization-panel"><div class="actions"><h2>{{ currentFarm.name }}</h2><button v-if="can('accounting_write')" class="button" @click="farmForm={...currentFarm}">Editar granja</button><button v-if="can('accounting_write')" class="button primary" @click="groupForm={farm_id:currentFarm.id,name:''}">Nou grup</button></div><p v-if="currentFarm.notes">{{ currentFarm.notes }}</p><p v-if="!currentGroups.length">Crea els grups amb què vols organitzar les despeses d’aquesta granja.</p><div v-for="group in currentGroups" :key="group.id" class="organization-row"><button class="button" @click="groupId=String(group.id);load()">{{ group.name }}</button><button v-if="can('accounting_write')" class="button" @click="groupForm={...group}">Canviar nom</button></div></section>
 <section class="panel organization-panel"><h2>Despeses classificades</h2><div class="table-wrap"><table><thead><tr><th>Factura</th><th>Proveïdor</th><th>Granja</th><th>Grup</th><th>Total factura</th><th></th></tr></thead><tbody><tr v-for="row in expenses" :key="row.id"><td>{{ row.reference||'Esborrany' }}<small class="trade-cell-note">{{ row.invoice_date }}</small></td><td>{{ row.supplier_name }}</td><td>{{ row.farm_name }}</td><td>{{ row.group_name||'Sense grup' }}</td><td>{{ row.total_amount??'Pendent' }} {{ row.currency }}</td><td><button class="button" @click="selectedExpense=row">Classificació</button></td></tr><tr v-if="!expenses.length"><td colspan="6">Sense despeses classificades amb aquests filtres.</td></tr></tbody></table></div></section>
 <RouterLink v-if="companyHasCapability(company,'pig_production')" to="/granjas/produccio">Dades anteriors de lots i producció</RouterLink>
 <FormDialog v-if="farmForm" :title="farmForm.id?'Editar granja':'Nova granja'" :busy="busy" @close="farmForm=null"><form class="organization-form" @submit.prevent="saveFarm"><label>Codi<input v-model="farmForm.code" required maxlength="20" pattern="[A-Za-z0-9_.-]+"></label><label>Nom<input v-model="farmForm.name" required maxlength="160"></label><label>Notes<textarea v-model="farmForm.notes" maxlength="2000"/></label><p v-if="error" role="alert">{{ error }}</p><button class="button primary" :disabled="busy">Guardar granja</button></form></FormDialog>
 <FormDialog v-if="groupForm" :title="groupForm.id?'Editar grup':'Nou grup'" :busy="busy" @close="groupForm=null"><form class="organization-form" @submit.prevent="saveGroup"><label>Nom del grup<input v-model="groupForm.name" required maxlength="160"></label><p v-if="error" role="alert">{{ error }}</p><button class="button primary" :disabled="busy">Guardar grup</button></form></FormDialog>
 <FormDialog v-if="selectedExpense" title="Classificació de la despesa" @close="selectedExpense=null;load()"><p>{{ selectedExpense.reference }} · {{ selectedExpense.supplier_name }}</p><FarmExpenseClassification :source-kind="selectedExpense.source_kind" :source-id="selectedExpense.source_id"/></FormDialog>
</template>
<style scoped>.organization-panel{padding:20px;margin:20px 0}.organization-panel h2{margin:0 0 12px}.organization-row{display:flex;align-items:center;gap:14px;margin:12px 0;flex-wrap:wrap}.organization-form{display:grid;gap:16px}.organization-form label{display:grid;gap:6px}</style>
